<?php

namespace App\Tailoring;

?>
<?php $paidAmount = paid((int) $order['id']);
$balance = cents($order['grand_total']) - $paidAmount; ?>
<div class="d-flex flex-wrap justify-content-between gap-3 mb-3"><div><p class="section-label"><?= t('Order details')?></p><h1 class="h3"><?= e($order['order_number'])?></h1><p class="small text-secondary"><?= e($order['customer_name'])?> · <?= e($order['customer_mobile'])?></p></div><div><a class="btn btn-outline-primary" href="/<?= $admin ? 'admin' : 'customer'?>/orders/<?= (int) $order['id']?>/receipt" target="_blank" rel="noopener"><?= t('Print receipt')?></a></div></div>
<?php progress($order['status']); ?>
<?php if (! $order['advance_satisfied']) { ?><div class="alert alert-warning"><?= t('Advance not fully received yet.')?> <?= t('Advance required')?>: <?= money($order['required_advance'])?>. <?= t('The order still proceeds; this is a reminder only.')?></div><?php } ?>
<div class="row g-4"><div class="col-lg-7"><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= t('Items')?></h2><div class="table-responsive"><table class="table"><thead><tr><th><?= t('Service')?></th><th><?= t('Qty')?></th><th><?= t('Stitching')?></th><th><?= t('Cloth')?></th><th><?= t('Amount')?></th></tr></thead><tbody><?php foreach ($items as $item) { ?><tr><td><?= e($item['service_name_snapshot'])?></td><td><?= (int) $item['quantity']?></td><td><?= money($item['stitching_price'])?></td><td><?= money($item['material_price'])?></td><td><?= money($item['line_total'])?></td></tr><?php } ?></tbody></table></div><p class="small text-secondary"><?= t('Confirmed delivery date')?>: <?= e($order['confirmed_delivery_date'] ?: '—')?></p><?php if ($order['notes']) { ?><p><?= nl2br(e($order['notes']))?></p><?php } ?><?php if ($order['self_measurement_acknowledged']) { ?><p class="small text-secondary"><?= t('Self-submitted measurement responsibility acknowledged.')?> <?= e($order['self_measurement_acknowledged_at'])?> UTC</p><?php } ?><?php foreach ($items as $item) {
    if ($item['measurement_version_id']) {
        $version = one('SELECT * FROM measurement_versions WHERE id=?', [$item['measurement_version_id']]); ?><details class="mb-3"><summary><?= e($item['service_name_snapshot'])?> · <?= t('Measurement version')?> <?= (int) $version['version_number']?></summary><dl class="row small mt-3"><?php foreach (MEASUREMENT_FIELDS as $key => $label) { ?><dt class="col-6"><?= t($label)?></dt><dd class="col-6"><?= e($version[$key] ?? '—')?></dd><?php } ?></dl></details><?php }
    } ?></div></div>
<?php if ($images) { ?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= t('Reference photos')?></h2><div class="d-flex flex-wrap gap-3"><?php foreach ($images as $image) { ?><a href="/<?= $admin ? 'admin' : 'customer'?>/orders/<?= (int) $order['id']?>/images/<?= (int) $image['id']?>" target="_blank" rel="noopener"><img class="php-reference" src="/<?= $admin ? 'admin' : 'customer'?>/orders/<?= (int) $order['id']?>/images/<?= (int) $image['id']?>" alt="<?= t('Reference photo')?>" width="120" height="120" loading="lazy"></a><?php } ?></div></div></div><?php } ?>
<?php if ($admin) { ?><div class="card"><div class="card-body"><h2 class="h5"><?= t('Order details')?></h2><form action="/admin/orders/<?= (int) $order['id']?>/details" method="post"><?= csrf_field()?><?php select_field('priority', 'Priority', ['NORMAL' => 'Normal', 'URGENT' => 'Urgent'], $order['priority']);
    field('confirmed_delivery_date', 'Confirmed delivery date', 'date', $order['confirmed_delivery_date']);
    textarea_field('notes', 'Notes', $order['notes']); ?><button class="btn btn-primary"><?= t('Save details')?></button></form></div></div><?php } ?></div><div class="col-lg-5"><div class="card mb-4"><div class="card-body"><h2 class="h5 mb-3"><?= t('Financial summary')?></h2><dl class="row"><dt class="col-7"><?= t('Grand total')?></dt><dd class="col-5 text-end"><?= money($order['grand_total'])?></dd><dt class="col-7"><?= t('Paid (verified)')?></dt><dd class="col-5 text-end"><?= money(decimal($paidAmount))?></dd><dt class="col-7"><?= t('Balance due')?></dt><dd class="col-5 text-end fw-bold"><?= money(decimal($balance))?></dd></dl>
<?php if ($admin) { ?><h3 class="h6 mt-4"><?= t('Status')?></h3><form action="/admin/orders/<?= (int) $order['id']?>/status" method="post" class="d-flex flex-wrap gap-2"><?= csrf_field()?><?php foreach (STATUSES as $status) {
    if ($status === $order['status']) {
        continue;
    }?><button class="btn btn-sm btn-outline-primary" name="status" value="<?= e($status)?>"><?= e($status)?></button><?php } ?></form><?php } ?></div></div>
<?php if ($admin && $balance > 0) { ?><div class="card mb-4"><div class="card-body"><h2 class="h5"><?= t('Record a payment')?></h2><form action="/admin/orders/<?= (int) $order['id']?>/payment" method="post"><?= csrf_field()?><input type="hidden" name="submission" value="<?= e($submission)?>"><?php field('amount', 'Amount (₹)', 'text', null, true);
    select_field('method', 'Method', ['CASH' => 'Cash', 'UPI' => 'UPI', 'ONLINE' => 'Online']);
    field('transaction_reference', 'Payment reference');
    textarea_field('note', 'Note'); ?><button class="btn btn-primary w-100"><?= t('Record payment')?></button></form></div></div><?php } ?>
<div class="card"><div class="card-body"><h2 class="h5"><?= t('Payment history')?></h2><?php foreach ($payments as $payment) { ?><div class="border-bottom py-3"><strong><?= money($payment['amount'])?></strong> · <?= e($payment['method'])?><br><small class="text-secondary"><?= e($payment['status'])?> · <?= e($payment['created_at'])?> UTC</small><br><a href="/<?= $admin ? 'admin' : 'customer'?>/payments/<?= (int) $payment['id']?>/receipt" target="_blank" rel="noopener"><?= t('Print receipt')?></a></div><?php } ?><?php if (! $payments) { ?><p class="small text-secondary"><?= t('No payments yet.')?></p><?php } ?></div></div></div></div>
